// isCurlyBrace returns true if the current token is an unquoted
// curly brace matching the given text ("{" or "}"). Quoted braces
// are treated as literal values, not as block delimiters.
func (d *Dispenser) isCurlyBrace(brace string) bool {
	if d.cursor < 0 || d.cursor >= len(d.tokens) {
